      text(at.getMonth() + 1 + "/" + at.getDate() + "  " + match.scores.join(" : "), 42, y + 49, 11, C.muted);
      text(match.bestMs === null ? "\u62A2\u8DD1\u51B3\u80DC" : match.bestMs + " ms", 348, y + 32, 21, C.blue, 700, "right", true);
