    button(24, 647, 342, 46, matches.length ? "\u6E05\u9664\u672C\u673A\u6218\u7EE9" : "\u6765\u4E00\u573A\u5BF9\u51B3", matches.length ? clearRecords : enterDuel, { fill: matches.length ? C.soft : C.blue, color: matches.length ? C.muted : C.cream });
